+var apiKey = configuration["OPENAI_API_KEY"]
+    ?? throw new InvalidOperationException(
+        "Set the OPENAI_API_KEY environment variable to run this agent.");
+
+var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";
+
+// Set up DI
+var services = new ServiceCollection();
+services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Information));
+
+services.AddChatClient(builder => builder
+    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));
+
+var provider = services.BuildServiceProvider();
+var chatClient = provider.GetRequiredService<IChatClient>();
+var logger = provider.GetRequiredService<ILogger<Program>>();
+
+// Create tools
+var notepad = new Notepad();
+var tools = new List<AITool>
+{
+    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
+    AIFunctionFactory.Create(notepad.TakeNote),
+    AIFunctionFactory.Create(notepad.GetNotes),
+};
+
+// Configure the agent
+var agent = new ChatClientAgent(chatClient, "ResearchAgent")
+{
+    Instructions = """
+        You are a research agent. Given a topic, you must:
+        1. Search the web for relevant information (perform 2-3 searches with different queries).
+        2. Take notes on the key findings from each search.
+        3. After gathering enough information, retrieve your notes and provide a comprehensive summary.
+        
+        Always search first, take notes, then summarize. Be thorough but concise.
+        """,
+    Tools = tools,
+};
+
+// Run the agent
+Console.WriteLine("=== Research Agent ===");
+Console.Write("Enter a research topic: ");
+var topic = Console.ReadLine()?.Trim();
+
+if (string.IsNullOrEmpty(topic))
+{
+    Console.WriteLine("No topic provided. Exiting.");
+    return;
+}
+
+logger.LogInformation("Researching topic: {Topic}", topic);
+
+var history = new List<ChatMessage>
+{
+    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
+};
+
+var options = new AgentInvokeOptions
+{
+    MaximumIterations = 10,
+};
+
+Console.WriteLine($"\nResearching: {topic}\n");
+
+await foreach (var message in agent.InvokeStreamingAsync(history, options))
+{
+    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
+    {
+        Console.Write(message.Text);
+    }
+}
+
+Console.WriteLine("\n\n=== Research Complete ===");
+
+// Display collected notes
+var allNotes = notepad.GetAllNotes();
+if (allNotes.Count > 0)
+{
+    Console.WriteLine($"\n📝 Notes collected ({allNotes.Count}):");
+    foreach (var note in allNotes)
+    {
+        Console.WriteLine($"  • {note}");
+    }
+}
+
+namespace ResearchAgent
+{
+    /// <summary>
+    /// Simulated web search tool that the agent can invoke.
+    /// Replace the implementation with a real search API (e.g., Bing Search) for production use.
+    /// </summary>
+    public static class WebSearchTool
+    {
+        [Description("Searches the web for information on a given query. Returns a list of relevant results.")]
+        public static Task<string> SearchWebAsync(
+            [Description("The search query string")] string query)
+        {
+            // Simulated search results for demonstration.
+            // In production, replace with a real search API call (Bing, Google, etc.)
+            var result = $"""
+                Search results for: "{query}"
+                
+                1. [Wikipedia] Overview article covering key aspects of "{query}" - provides historical context, 
+                   current developments, and major perspectives on the topic.
+                
+                2. [Research Paper] Recent academic study on "{query}" findings include new data points 
+                   and analysis from leading researchers in the field.
+                
+                3. [News Article] Latest developments related to "{query}" - covers recent events, 
+                   industry trends, and expert commentary.
+                
+                Note: This is a simulated search. To use real web search, configure a Bing Search API key 
+                and replace this implementation.
+                """;
+
+            return Task.FromResult(result);
+        }
+    }
+
+    /// <summary>
+    /// Note-taking tool that allows the agent to record and retrieve research findings.
+    /// </summary>
+    public class Notepad
+    {
+        private readonly List<string> _notes = [];
+
+        [Description("Records a note about a research finding. Use this to save important information discovered during research.")]
+        public string TakeNote([Description("The note content to record")] string note)
+        {
+            _notes.Add(note);
+            return $"Note recorded ({_notes.Count} total).";
+        }
+
+        [Description("Retrieves all notes taken during this research session.")]
+        public string GetNotes()
+        {
+            if (_notes.Count == 0)
+                return "No notes have been taken yet.";
+
+            return $"Research notes ({_notes.Count}):\n" +
+                string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
+        }
+
+        public List<string> GetAllNotes() => [.. _notes];
+    }
+}

